(function(){
let records=[],departments=[],truncated=false;
const filters={type:'',department:'',from:'',to:'',search:''};
const safe=value=>esc(String(value??''));
const titles={1:'日常火源自行檢查表',2:'防火避難設施自行檢查表',3:'消防安全設備自行檢查紀錄表'};
const dateTime=value=>value?new Intl.DateTimeFormat('zh-TW',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(value)):'';
const departmentName=id=>{const d=departments.find(x=>x.id===id);return d?.name_zh||d?.name_vi||d?.name_en||'';};
function matches(r){const signed=String(r.confirmed_at||'').slice(0,10),term=filters.search.trim().toLocaleLowerCase();return (!filters.type||String(r.form_type)===filters.type)&&(!filters.department||r.department_id===filters.department)&&(!filters.from||signed>=filters.from)&&(!filters.to||signed<=filters.to)&&(!term||[r.responsible_area,r.implementer_name,r.manager_name,r.manager_signature].some(v=>String(v||'').toLocaleLowerCase().includes(term)));}
function render(){const shown=records.filter(matches);$('#content').innerHTML=`${window.fireFormTabs(4)}<section class="fire-approval-history"><h2>簽核紀錄 <small>Lịch sử xác nhận</small></h2><p class="fire-intro">集中查閱附件 1～3 已由防火管理人確認的表單。可依附件、部門、簽核日期及姓名查找，點選「檢視原表單」查看完整內容與簽章。</p><div class="fire-history-filters"><label>附件<select id="fireHistoryType" class="select"><option value="">全部附件</option>${[1,2,3].map(n=>`<option value="${n}" ${filters.type===String(n)?'selected':''}>附件 ${n}</option>`).join('')}</select></label><label>部門<select id="fireHistoryDepartment" class="select"><option value="">全部部門</option>${departments.map(d=>`<option value="${safe(d.id)}" ${filters.department===d.id?'selected':''}>${safe(departmentName(d.id))}</option>`).join('')}</select></label><label>簽核起日<input id="fireHistoryFrom" type="date" class="select" value="${safe(filters.from)}"></label><label>簽核迄日<input id="fireHistoryTo" type="date" class="select" value="${safe(filters.to)}"></label><label>姓名或負責區域<input id="fireHistorySearch" type="search" class="select" value="${safe(filters.search)}" placeholder="輸入關鍵字"></label></div><p class="fire-history-count">共 ${shown.length} 筆已簽核文件${truncated?'；資料量較多，清單僅載入每類最新 1,000 筆。':''}</p><div class="table-wrap"><table class="matrix"><thead><tr><th>簽核時間</th><th>文件</th><th>檢查日期／月份</th><th>部門</th><th>負責區域</th><th>實施人員</th><th>防火管理人</th><th>操作</th></tr></thead><tbody>${shown.map(r=>`<tr><td>${safe(dateTime(r.confirmed_at))}</td><td>附件 ${r.form_type}<br>${safe(titles[r.form_type])}</td><td>${safe(r.form_type===1?String(r.inspection_month||'').slice(0,7):r.inspection_date)}</td><td>${safe(departmentName(r.department_id))}</td><td>${safe(r.responsible_area)}</td><td>${safe(r.implementer_name)}</td><td>${safe(r.manager_name)}</td><td><button type="button" class="btn secondary" data-fire-history-open="${safe(r.id)}">檢視原表單</button></td></tr>`).join('')||'<tr><td colspan="8" class="empty-note">沒有符合條件的已簽核文件</td></tr>'}</tbody></table></div></section>`;
 window.bindFireFormTabs();
 for(const [key,id] of [['type','fireHistoryType'],['department','fireHistoryDepartment'],['from','fireHistoryFrom'],['to','fireHistoryTo']])$('#'+id).onchange=e=>{filters[key]=e.target.value;render();};
 $('#fireHistorySearch').onchange=e=>{filters.search=e.target.value;render();};
 document.querySelectorAll('[data-fire-history-open]').forEach(button=>button.onclick=()=>{const found=records.find(r=>r.id===button.dataset.fireHistoryOpen);if(!found)return;if(found.form_type===1)window.openFireDailyRecord(found.id);else window.openFireAttachmentRecord(found.form_type,found.id);});
}
window.renderFireApprovalHistory=async function(){try{const result=await api({action:'fire_approval_history'});records=result.records||[];departments=result.departments||[];truncated=!!result.truncated;render();}catch(e){$('#content').innerHTML=`${window.fireFormTabs(4)}<div class="empty-note">無法讀取簽核紀錄：${safe(e.message)}</div>`;window.bindFireFormTabs();}};
})();
